PACKET=json.loads('{"root":"/home/qian/heptabao-current-pocket4-4bde9-qualification-20261106-r1","out":"/home/qian/heptabao-current-pocket4-4bde9-qualification-20261106-r1/control-r2","hostname":"qian-ThinkPad-X230","files":[{"name":"x230_current_candidate_qualification.py","bytes":34679,"sha256":"abb8adee9483696df7e38369dbb0436cd578721d4b6bde18a06dd0218ee1e0d0","text":"#!/usr/bin/env python3\\n\\"\\"\\"Admit the frozen 4bde9 Pocket4 build, then run original full34 and comparison69 once.\\n\\nRun with Python -I -S -B. The candidate checkout stays clean at the build commit;\\nthis successor controller may live in a later QA checkout. The comparison driver\\nis the retained, unchanged X230 original, supplied by absolute path. No existing\\nservice endpoint, production credential, retry, deletion or cutover is accepted.\\nDR25 supplies the existing receipt parser, file custody and process ownership.\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport contextlib\\nfrom decimal import Decimal\\nimport hashlib\\nimport importlib\\nimport ipaddress\\nimport json\\nimport math\\nimport os\\nfrom pathlib import Path\\nimport platform\\nimport re\\nimport runpy\\nimport subprocess\\nimport sys\\nimport time\\nfrom types import SimpleNamespace\\nfrom urllib.parse import urlsplit\\n\\nBUILD_COMMIT = \\"4bde9aee03fcd27c59e13607e529b1cee594b249\\"\\nBUILD_TREE = \\"f08493a23f8ea0637073651231865ea9607b790e\\"\\nSELECTION_SHA256 = \\"869feff2d8672fe37a26a2fb671cdc853b3c9d7f889edfe76650eed8103f44e9\\"\\nBUILD_CONTROLLER_SHA256 = \\"c8ef09b133312149eecc1886322cc96dcecda18c637b0db9fc3a5e917b3f6564\\"\\nBUILD_JOB_ID = \\"1a1b2367cb2-fc05-7cfc\\"\\nABI_CAPTURE_SHA256 = \\"3f49130cc7dbf5c1a9bde8e0a83d26a7280d41eb59b03fb9c5f48a0dc7a1cd63\\"\\nABI_PARSER_SHA256 = \\"1b6594238cfaf26a2411ec422a858f9958626c98e2d5dece8464f24ee8ed73b4\\"\\nCOMPARISON_SHA256 = \\"fd88ed0b8f1c1010e79f9393dfbf6464cabcac48ece8c6e448a64b7ccc45272e\\"\\nWORKLOAD_PINS = {\\n    \\"qa/openbao-acceptance/kv2_271_lossless_native_live.py\\":\\n        \\"383176647f0670837f40f3989496c6d1c902f8503dfa006d386b75877436b581\\",\\n    \\"qa/openbao-acceptance/acceptance.py\\":\\n        \\"8312c400ec5f0946f8a87fb3241bf8db832ddd04763010af7245d6557f55f94d\\",\\n}\\nORACLE_PINS = {\\n    \\"oracle_binary\\": \\"535cf827b13753046757f5ec8b97ae0ef21f10a40ffe673f0d5e75616170f5ea\\",\\n    \\"oracle_archive\\": \\"0e2f1ce10d124e03112b50dd2fbec6b78003783253bc3a91587938f39d1e2243\\",\\n}\\nTOOLCHAIN_PINS = {\\n    \\"cargo\\": \\"ff3022fcbd13b08434ea7afde9a0ef9d5b3f5c17b5fc7a40031be3ee000a6a24\\",\\n    \\"rustc\\": \\"3690cc576ede140504698405d5d8fa3826aaadbe71699c6c4ed0a565d6f493e2\\",\\n    \\"rustfmt\\": \\"5005cdcd39ded526dca8fa6ccd716d42fc7da54469034e055dbf54649bec7877\\",\\n}\\nPRODUCER_ROOT = Path(\\"/home/alex/heptabao-kv2-ha-convergence-4bde9-authbus-20261106-r1\\")\\nPRODUCER_BUILD = PRODUCER_ROOT / \\"build-test-r1\\"\\nPRODUCER_SOURCE = PRODUCER_ROOT / \\"source-4bde9\\"\\nTOOLCHAIN = Path(\\"/home/alex/.rustup/toolchains/1.98.0-x86_64-unknown-linux-gnu/bin\\")\\nMODULES = tuple(sorted(\\"core,kv,token,transit,pki,totp,userpass,approle,identity,wrapping,edge_tls,system,operations\\".split(\\",\\")))\\nDEPENDENCY_ROOTS = (\\"qa/openbao-acceptance\\", \\"qa/single-node\\", \\"clients/python\\", \\"tools/migration\\")\\nMAX_JSON_BYTES = 8 * 1024 * 1024\\n\\n\\nclass AdmissionFailure(RuntimeError):\\n    \\"\\"\\"Closed diagnostic labels only; never credentials or command output.\\"\\"\\"\\n\\n\\ndef need(value, label):\\n    if not value:\\n        raise AdmissionFailure(label)\\n\\n\\ndef git(root, *args):\\n    return subprocess.check_output([\\"/usr/bin/git\\", \\"-C\\", str(root), *args],\\n        stderr=subprocess.DEVNULL, timeout=15,\\n        env={\\"PATH\\": \\"/usr/bin:/bin\\", \\"LC_ALL\\": \\"C\\", \\"GIT_OPTIONAL_LOCKS\\": \\"0\\"})\\n\\n\\ndef source_snapshot(root):\\n    need(root.is_absolute() and root.resolve(strict=True) == root, \\"canonical_source_required\\")\\n    need(git(root, \\"rev-parse\\", \\"HEAD\\").decode().strip() == BUILD_COMMIT\\n         and git(root, \\"rev-parse\\", \\"HEAD^{tree}\\").decode().strip() == BUILD_TREE,\\n         \\"frozen_4bde9_source_required\\")\\n    need(not git(root, \\"status\\", \\"--porcelain\\", \\"--untracked-files=all\\"), \\"clean_candidate_source_required\\")\\n    rows = git(root, \\"ls-tree\\", \\"-rz\\", \\"HEAD\\", \\"--\\", *DEPENDENCY_ROOTS).split(b\\"\\\\0\\")\\n    pins = {}\\n    for row in filter(None, rows):\\n        metadata, raw_path = row.split(b\\"\\\\t\\", 1)\\n        relative = os.fsdecode(raw_path)\\n        if not relative.endswith(\\".py\\") or \\"/evidence/\\" in relative or \\"/tests/\\" in relative:\\n            continue\\n        mode, kind, object_id = metadata.split()\\n        path = root / relative\\n        need(mode in (b\\"100644\\", b\\"100755\\") and kind == b\\"blob\\"\\n             and path.resolve(strict=True) == path and path.is_file(), \\"source_dependency_regular_required\\")\\n        raw = path.read_bytes()\\n        need(hashlib.sha1(b\\"blob \\" + str(len(raw)).encode() + b\\"\\\\0\\" + raw).hexdigest()\\n             == object_id.decode(), \\"source_dependency_differs_from_frozen_tree\\")\\n        pins[relative] = hashlib.sha256(raw).hexdigest()\\n    need(all(pins.get(name) == value for name, value in WORKLOAD_PINS.items()), \\"original_workloads_required\\")\\n    # -B prevents writes, but would still read preexisting bytecode. No ignored\\n    # bytecode or untracked Python module may replace a bound source dependency.\\n    for relative in DEPENDENCY_ROOTS:\\n        for path in (root / relative).rglob(\\"*\\"):\\n            name = path.relative_to(root).as_posix()\\n            if \\"/evidence/\\" in name or \\"/tests/\\" in name:\\n                continue\\n            need(path.suffix not in (\\".pyc\\", \\".pyo\\", \\".so\\"), \\"cached_source_dependency_refused\\")\\n            if path.suffix == \\".py\\":\\n                need(name in pins, \\"untracked_source_dependency_refused\\")\\n    return {\\"commit\\": BUILD_COMMIT, \\"tree\\": BUILD_TREE, \\"dependencies\\": pins}\\n\\n\\ndef load_dependencies(source):\\n    sys.path[:0] = [str(source / p) for p in\\n                   (\\"qa/openbao-acceptance\\", \\"qa/single-node\\", \\"clients/python\\")]\\n    modules = {}\\n    for name in (\\"kv2_native_fresh_directory_dr_live\\", \\"kv2_dr_process_custody\\", \\"acceptance\\",\\n                 \\"official_openbao_launcher\\"):\\n        module = importlib.import_module(name)\\n        need(Path(module.__file__).resolve() == source / \\"qa/openbao-acceptance\\" / (name + \\".py\\"),\\n             \\"dependency_import_identity_mismatch\\")\\n        modules[name] = module\\n    dr = modules[\\"kv2_native_fresh_directory_dr_live\\"]\\n    need(dr.ROOT == source and dr.full.ROOT == source, \\"workload_import_root_mismatch\\")\\n    return SimpleNamespace(dr=dr, full=dr.full, custody=modules[\\"kv2_dr_process_custody\\"],\\n        acceptance=modules[\\"acceptance\\"], launcher=modules[\\"official_openbao_launcher\\"])\\n\\n\\ndef selected_groups(selection):\\n    return [g for key in (\\"legacy_groups\\", \\"legacy_additional_groups\\", \\"added_groups\\")\\n            for g in selection[key]]\\n\\n\\ndef expected_build_steps(selection):\\n    \\"\\"\\"The pinned producer controller\'s closed command inventory.\\"\\"\\"\\n    entries = [\\n        (\\"00-source-head\\", [\\"/usr/bin/git\\", \\"rev-parse\\", \\"HEAD\\"], 30),\\n        (\\"01-preserved-format-diff\\", [\\"/usr/bin/git\\", \\"diff\\", \\"--binary\\", \\"HEAD\\"], 30),\\n        (\\"02-untracked\\", [\\"/usr/bin/git\\", \\"ls-files\\", \\"--others\\", \\"--exclude-standard\\"], 30),\\n        (\\"03-bundle-verify\\", [\\"/usr/bin/git\\", \\"bundle\\", \\"verify\\", str(PRODUCER_BUILD / \\"candidate.bundle\\")], 30),\\n        (\\"04-fetch\\", [\\"/usr/bin/git\\", \\"fetch\\", str(PRODUCER_BUILD / \\"candidate.bundle\\"), \\"HEAD\\"], 30),\\n        (\\"05-canonical-tree\\", [\\"/usr/bin/git\\", \\"rev-parse\\", BUILD_COMMIT + \\"^{tree}\\"], 30),\\n        (\\"06-canonical-parent\\", [\\"/usr/bin/git\\", \\"rev-parse\\", BUILD_COMMIT + \\"^\\"], 30),\\n        (\\"07-stage-exact-format\\", [\\"/usr/bin/git\\", \\"add\\", \\"--update\\"], 30),\\n        (\\"08-format-working-tree\\", [\\"/usr/bin/git\\", \\"write-tree\\"], 30),\\n        (\\"09-checkout-canonical\\", [\\"/usr/bin/git\\", \\"checkout\\", \\"--detach\\", BUILD_COMMIT], 30),\\n        (\\"10-clean-source\\", [\\"/usr/bin/git\\", \\"status\\", \\"--porcelain\\"], 30),\\n        (\\"11-fsck\\", [\\"/usr/bin/git\\", \\"fsck\\", \\"--full\\", \\"--strict\\"], 60),\\n        (\\"12-format-check\\", [str(TOOLCHAIN / \\"cargo\\"), \\"fmt\\", \\"--all\\", \\"--\\", \\"--check\\"], 60),\\n    ]\\n    for label, key, cap in ((\\"13-normal-release-build\\", \\"server_release\\", 1800),\\n                            (\\"14-server-libtest-build\\", \\"server_libtest\\", 3600),\\n                            (\\"15-peer-libtest-build\\", \\"peer_libtest\\", 3600)):\\n        entries.append((label, selection[\\"build_examples\\"][key], cap))\\n    for crate in (\\"heptabao-server\\", \\"heptabao-ha-service\\"):\\n        entries.append((crate + \\"-list\\", [str(PRODUCER_BUILD / \\"artifacts\\" / (crate + \\"-libtest\\")), \\"--list\\"], 30))\\n    for index, group in enumerate(selected_groups(selection)):\\n        for number, suffix in enumerate(group.get(\\"argv_suffixes\\", [group.get(\\"argv_suffix\\")])):\\n            entries.append((f\'test-{index:02d}-{group[\\"label\\"]}-{number:02d}\',\\n                [str(PRODUCER_BUILD / \\"artifacts\\" / (group[\\"crate\\"] + \\"-libtest\\")), *suffix], group[\\"runtime_seconds\\"]))\\n    entries.extend(((\\"99-final-source-head\\", [\\"/usr/bin/git\\", \\"rev-parse\\", \\"HEAD\\"], 30),\\n                    (\\"99-final-source-clean\\", [\\"/usr/bin/git\\", \\"status\\", \\"--porcelain\\"], 30)))\\n    return entries\\n\\n\\ndef finite_number(value):\\n    return type(value) in (int, float, Decimal) and math.isfinite(value)\\n\\n\\ndef validate_receipt(receipt, selection, selection_sha, server, seed, dr):\\n    need(receipt.get(\\"status\\") == \\"passed\\" and receipt.get(\\"failure\\") is None,\\n         \\"terminal_successful_build_required\\")\\n    need(selection_sha == SELECTION_SHA256 and receipt.get(\\"source_commit\\") == BUILD_COMMIT\\n         and receipt.get(\\"source_tree\\") == BUILD_TREE\\n         and receipt.get(\\"controller_sha256\\") == BUILD_CONTROLLER_SHA256, \\"current_build_identity_required\\")\\n    # Reuse DR25\'s unique 107 names, 90/17 split, actual enumeration and per-result\\n    # failed/ignored/measured checks. A previous normal61 receipt cannot pass.\\n    binding = dr.validate_build_receipt(receipt, BUILD_COMMIT, server, seed, selection, selection_sha)\\n    need(receipt.get(\\"toolchain_pins\\") == TOOLCHAIN_PINS\\n         and receipt.get(\\"build_environment_overrides\\") == selection[\\"original_build\\"][\\"env\\"]\\n         and receipt.get(\\"compiler_wrappers_disabled\\") is True\\n         and receipt.get(\\"ambient_build_overrides_inherited\\") is False\\n         and receipt.get(\\"explicit_compiler\\") == str(TOOLCHAIN / \\"rustc\\"), \\"normal_producer_build_profile_required\\")\\n    need(receipt.get(\\"automatic_retry\\") is False and receipt.get(\\"deadline_renewed\\") is False\\n         and type(receipt.get(\\"outer_budget_seconds\\")) is int and receipt[\\"outer_budget_seconds\\"] == 12000\\n         and finite_number(receipt.get(\\"elapsed_seconds\\")) and 0 < receipt[\\"elapsed_seconds\\"] < 12000\\n         and finite_number(receipt.get(\\"created_at_unix\\")) and finite_number(receipt.get(\\"finished_at_unix\\"))\\n         and 0 < receipt[\\"created_at_unix\\"] <= receipt[\\"finished_at_unix\\"], \\"terminal_original_build_budget_required\\")\\n    need(all(receipt.get(key) is False for key in (\\"production_changed\\", \\"production_server_started\\",\\n         \\"formal_kv2_qualified\\", \\"physical_ha_qualified\\", \\"authbus_migration_qualified\\",\\n         \\"full_replacement_qualified\\")), \\"build_receipt_scope_mismatch\\")\\n    names = {\\"heptabao-server\\", \\"heptabao-seed\\", \\"heptabao-server-libtest\\", \\"heptabao-ha-service-libtest\\"}\\n    need(set(receipt[\\"artifacts\\"]) == names, \\"exact_build_artifact_set_required\\")\\n    for name, artifact in receipt[\\"artifacts\\"].items():\\n        peer, test = name == \\"heptabao-ha-service-libtest\\", name.endswith(\\"-libtest\\")\\n        package = \\"heptabao-ha-service\\" if peer else \\"heptabao-server\\"\\n        entry = \\"src/lib.rs\\" if test else \\"src/bin/heptabao-seed.rs\\" if name == \\"heptabao-seed\\" else \\"src/main.rs\\"\\n        profile = {\\"opt_level\\": \\"3\\", \\"debuginfo\\": 0, \\"debug_assertions\\": True, \\"overflow_checks\\": True, \\"test\\": test}\\n        features = [\\"default\\", \\"native-v6-peer-ingress\\"] if peer else [\\"default\\", \\"native-v6-ha\\", \\"native-v6-storage\\"]\\n        need(artifact.get(\\"source_commit\\") == BUILD_COMMIT and artifact.get(\\"source_tree\\") == BUILD_TREE\\n             and artifact.get(\\"normal_features_profile_and_source_verified\\") is True\\n             and artifact.get(\\"path\\") == str(PRODUCER_BUILD / \\"artifacts\\" / name)\\n             and artifact.get(\\"cargo_source_entry\\") == str(PRODUCER_SOURCE / \\"crates\\" / package / entry)\\n             and artifact.get(\\"cargo_package_id\\", \\"\\").startswith(\\"path+file://\\" + str(PRODUCER_SOURCE / \\"crates\\" / package) + \\"#\\")\\n             and artifact.get(\\"cargo_features\\") == features and artifact.get(\\"cargo_profile\\") == profile\\n             and all(type(artifact[\\"cargo_profile\\"].get(key)) is type(value) for key, value in profile.items())\\n             and type(artifact.get(\\"bytes\\")) is int and artifact[\\"bytes\\"] > 0\\n             and re.fullmatch(r\\"[0-9a-f]{64}\\", artifact.get(\\"sha256\\", \\"\\")), \\"normal_artifact_source_or_features_mismatch\\")\\n    expected, steps = expected_build_steps(selection), receipt.get(\\"steps\\", [])\\n    need([step.get(\\"step\\") for step in steps] == [row[0] for row in expected], \\"exact_completed_build_steps_required\\")\\n    for step, (label, argv, cap) in zip(steps, expected):\\n        cleanup = step.get(\\"owned_group_cleanup\\", {})\\n        need(step.get(\\"argv\\") == argv and type(step.get(\\"attempts\\")) is int and step[\\"attempts\\"] == 1\\n             and type(step.get(\\"exit_code\\")) is int and step[\\"exit_code\\"] == 0\\n             and step.get(\\"timed_out\\") is False and \\"exception_type\\" not in step\\n             and step.get(\\"unexpected_live_descendants_on_success\\") is False\\n             and cleanup.get(\\"all_owned_processes_gone\\") is True and cleanup.get(\\"abnormal_exit\\") is False\\n             and cleanup.get(\\"remaining_before_cleanup\\") == [] and cleanup.get(\\"remaining_after_cleanup\\") == []\\n             and cleanup.get(\\"signals\\") == [] and \\"cleanup_error_type\\" not in cleanup,\\n             \\"build_step_not_terminal_success\\")\\n        need(step.get(\\"requested_cap_seconds\\") == cap and finite_number(step.get(\\"effective_budget_seconds\\"))\\n             and 0 < step[\\"effective_budget_seconds\\"] <= cap, \\"build_step_budget_changed\\")\\n        need(type(step.get(\\"pid\\")) is int and step[\\"pid\\"] > 0\\n             and finite_number(step.get(\\"seconds\\")) and step[\\"seconds\\"] >= 0\\n             and finite_number(step.get(\\"started_at_unix\\")) and step[\\"started_at_unix\\"] > 0,\\n             \\"build_step_execution_observation_missing\\")\\n        for stream in (\\"stdout\\", \\"stderr\\"):\\n            need(type(step.get(stream + \\"_bytes\\")) is int and step[stream + \\"_bytes\\"] >= 0\\n                 and re.fullmatch(r\\"[0-9a-f]{64}\\", step.get(stream + \\"_sha256\\", \\"\\")), \\"build_step_output_binding_missing\\")\\n    for group, expected_group in zip(receipt[\\"groups\\"], selected_groups(selection)):\\n        need(group.get(\\"budget_renewed_per_case\\") is False\\n             and group.get(\\"original_group_budget_seconds\\") == expected_group[\\"runtime_seconds\\"],\\n             \\"original_group_budget_required\\")\\n    return binding\\n\\n\\ndef pinned_json(path, dr, expected_sha=None):\\n    pin = dr.file_pin(path, private=True)\\n    raw = dr.full.private_read(path, MAX_JSON_BYTES)\\n    need(hashlib.sha256(raw).hexdigest() == pin[\\"sha256\\"]\\n         and (expected_sha is None or pin[\\"sha256\\"] == expected_sha), \\"receipt_bytes_or_expected_pin_mismatch\\")\\n    return dr.full.decode(raw), pin\\n\\n\\ndef comparison_cases(acceptance):\\n    # The unchanged source declares 68 CASES entries and records one additional\\n    # actual result in Suite.totp_cases -> mount(\\"totp\\"). Keep that original\\n    # 69th observation mandatory instead of editing the retained workload.\\n    declared = {module + \\".\\" + name for module in MODULES for name in acceptance.CASES[module]}\\n    need(set(acceptance.CASES) == set(MODULES) and len(declared) == 68\\n         and \\"totp.mount\\" not in declared, \\"original_comparison69_contract_required\\")\\n    return declared | {\\"totp.mount\\"}\\n\\n\\ndef load_abi_guards(dr):\\n    \\"\\"\\"Use the already reviewed capture/parser bytes, never cached bytecode.\\"\\"\\"\\n    modules, pins = {}, {}\\n    for name, expected in ((\\"x230_native_abi_capture\\", ABI_CAPTURE_SHA256),\\n                           (\\"x230_native_abi_admission\\", ABI_PARSER_SHA256)):\\n        path = Path(__file__).resolve().with_name(name + \\".py\\")\\n        pin = dr.file_pin(path)\\n        need(pin[\\"uid\\"] == os.geteuid() and not pin[\\"mode\\"] & 0o022 and pin[\\"bytes\\"] <= 65536,\\n             \\"owned_reviewed_abi_source_custody\\")\\n        raw = path.read_bytes()\\n        need(hashlib.sha256(raw).hexdigest() == expected == pin[\\"sha256\\"],\\n             \\"reviewed_adjacent_abi_guard_required\\")\\n        need(dr.file_pin(path) == pin, \\"abi_guard_source_changed_while_reading\\")\\n        namespace = {\\"__name__\\": \\"bound_\\" + name, \\"__file__\\": str(path)}\\n        exec(compile(raw, str(path), \\"exec\\"), namespace)\\n        modules[name], pins[name] = namespace, pin\\n    return modules[\\"x230_native_abi_capture\\"], modules[\\"x230_native_abi_admission\\"], pins\\n\\n\\ndef canonical_static_compatibility(value):\\n    \\"\\"\\"Preserve every requirement row while ignoring discovery-only row order.\\"\\"\\"\\n    need(type(value) is dict and type(value.get(\\"requirements\\")) is list,\\n         \\"static_compatibility_requirements_shape\\")\\n    rows, identities = value[\\"requirements\\"], set()\\n    for row in rows:\\n        need(type(row) is dict and set(row) == {\\"origin\\", \\"provider\\", \\"required_versions\\"}\\n             and all(type(row[key]) is str and row[key] for key in (\\"origin\\", \\"provider\\"))\\n             and type(row[\\"required_versions\\"]) is list and row[\\"required_versions\\"]\\n             and all(type(version) is str and version for version in row[\\"required_versions\\"]),\\n             \\"static_compatibility_requirement_row_shape\\")\\n        versions = row[\\"required_versions\\"]\\n        need(versions == sorted(versions) and len(versions) == len(set(versions)),\\n             \\"static_compatibility_requirement_versions_exact\\")\\n        identity = (row[\\"origin\\"], row[\\"provider\\"])\\n        need(identity not in identities, \\"static_compatibility_requirement_rows_unique\\")\\n        identities.add(identity)\\n    # JSON sorts provider object keys, whereas the original collector discovers\\n    # recursive providers incrementally. Requirement row order carries no ABI\\n    # meaning; all rows, versions and other compatibility fields remain exact.\\n    return dict(value, requirements=sorted(rows, key=lambda row: (row[\\"origin\\"], row[\\"provider\\"])))\\n\\n\\ndef validate_static_admission(value, terminal, job, receipt, capture, parser):\\n    capture[\\"require_terminal\\"](terminal, job)\\n    need(value.get(\\"schema\\") == \\"heptabao.current-native-static-abi-capture.v1\\"\\n         and value.get(\\"status\\") == \\"passed\\" and value.get(\\"role\\") == \\"receiver\\"\\n         and value.get(\\"hostname\\") == \\"qian-ThinkPad-X230\\"\\n         and value.get(\\"source_commit\\") == BUILD_COMMIT and value.get(\\"source_tree\\") == BUILD_TREE\\n         and value.get(\\"normal107_job_id\\") == BUILD_JOB_ID\\n         and value.get(\\"static_receiver_compatibility_qualified\\") is True\\n         and value.get(\\"inputs_unchanged\\") is True\\n         and value.get(\\"controller\\", {}).get(\\"sha256\\") == ABI_CAPTURE_SHA256\\n         and value.get(\\"parser\\", {}).get(\\"sha256\\") == ABI_PARSER_SHA256\\n         and type(value.get(\\"target_binary_executions\\")) is int and value[\\"target_binary_executions\\"] == 0\\n         and value.get(\\"production_changed\\") is False\\n         and value.get(\\"actual_x230_runtime_qualified\\") is False\\n         and value.get(\\"full_replacement_qualified\\") is False\\n         and value.get(\\"deadline_renewed\\") is False and value.get(\\"automatic_retry\\") is False,\\n         \\"completed_current_receiver_static_capture_required\\")\\n    need(set(value.get(\\"inputs\\", {})) == {\\"producer_receipt\\", \\"producer_terminal\\"}\\n         and set(value.get(\\"tools\\", {})) == {\\"readelf\\", \\"ldconfig\\"}, \\"closed_static_capture_input_set\\")\\n    expected = {name: receipt[\\"artifacts\\"][name] for name in (\\"heptabao-server\\", \\"heptabao-seed\\")}\\n    comparison = parser[\\"verify_compatibility\\"](value[\\"artifacts\\"], value[\\"providers\\"],\\n        expected_artifact_pins=expected, interpreter_path=\\"/lib64/ld-linux-x86-64.so.2\\",\\n        interpreter_resolved_path=value[\\"interpreter_pin\\"][\\"path\\"])\\n    need(canonical_static_compatibility(comparison)\\n         == canonical_static_compatibility(value.get(\\"compatibility\\")),\\n         \\"original_static_compatibility_recomputed\\")\\n    aliases = value.get(\\"provider_alias_bindings\\", {})\\n    candidates = {path for paths in value.get(\\"provider_lookup_candidates\\", {}).values() for path in paths}\\n    need(set(value.get(\\"provider_lookup_candidates\\", {})) == set(value[\\"providers\\"])\\n         and set(aliases) == candidates and candidates, \\"complete_original_provider_alias_set\\")\\n    for name, paths in value[\\"provider_lookup_candidates\\"].items():\\n        need(paths and len(paths) == len(set(paths))\\n             and all(aliases[path].get(\\"path\\") == path\\n                     and aliases[path].get(\\"resolved_path\\") == value[\\"providers\\"][name][\\"pin\\"][\\"path\\"]\\n                     for path in paths), \\"provider_alias_to_canonical_file_binding\\")\\n    # Hash and stat all current receiver libraries/tools/input originals, check\\n    # every logical loader alias, and recheck interpreter/cache immediately\\n    # before the real fixtures. This launches no system or candidate program.\\n    fresh = capture[\\"Capture\\"]({\\"role\\": \\"receiver\\", \\"interpreter_path\\": \\"/lib64/ld-linux-x86-64.so.2\\"},\\n                               None, time.monotonic() + 60, parser)\\n    fresh.inputs, fresh.tools = value[\\"inputs\\"], value[\\"tools\\"]\\n    fresh.recheck(value)\\n    return {\\"static_compatibility\\": comparison, \\"provider_alias_bindings\\": aliases,\\n            \\"receiver_terminal_job_id\\": job, \\"receiver_current_pins_rechecked\\": True,\\n            \\"actual_x230_runtime_qualified_by_admission\\": False}\\n\\n\\ndef admit(args, deps, source):\\n    dr = deps.dr\\n    pins = {name: dr.file_pin(getattr(args, name)) for name in\\n            (\\"binary\\", \\"seed_binary\\", \\"comparison_driver\\", \\"oracle_binary\\", \\"oracle_archive\\")}\\n    for name in (\\"binary\\", \\"seed_binary\\"):\\n        pin = pins[name]\\n        need(pin[\\"uid\\"] == os.geteuid() and pin[\\"mode\\"] & 0o100 and not pin[\\"mode\\"] & 0o077,\\n             \\"owned_private_executable_required\\")\\n    need(pins[\\"comparison_driver\\"][\\"sha256\\"] == COMPARISON_SHA256, \\"unchanged_comparison_driver_required\\")\\n    need(all(pins[name][\\"sha256\\"] == digest for name, digest in ORACLE_PINS.items()), \\"official_271_pair_required\\")\\n    receipt, pins[\\"build_receipt\\"] = pinned_json(args.build_receipt, dr, args.build_receipt_sha256)\\n    selection_path = args.build_receipt.parent / \\"test-selection.public.json\\"\\n    selection, pins[\\"selection\\"] = pinned_json(selection_path, dr, SELECTION_SHA256)\\n    binding = validate_receipt(receipt, selection, pins[\\"selection\\"][\\"sha256\\"],\\n                               pins[\\"binary\\"], pins[\\"seed_binary\\"], dr)\\n    capture, parser, guard_pins = load_abi_guards(dr)\\n    pins.update(guard_pins)\\n    terminal, pins[\\"normal107_terminal\\"] = pinned_json(args.normal107_terminal, dr, args.normal107_terminal_sha256)\\n    capture[\\"require_terminal\\"](terminal, BUILD_JOB_ID)\\n    abi, pins[\\"abi_receipt\\"] = pinned_json(args.abi_receipt, dr, args.abi_receipt_sha256)\\n    abi_terminal, pins[\\"abi_terminal\\"] = pinned_json(args.abi_terminal, dr, args.abi_terminal_sha256)\\n    abi_binding = validate_static_admission(abi, abi_terminal, args.abi_job_id, receipt, capture, parser)\\n    need(deps.full.HTTP_SECONDS == 15 and deps.full.MIGRATION_SECONDS == 360\\n         and len(deps.full.CHECKS) == 31, \\"original_full34_contract_required\\")\\n    comparison_cases(deps.acceptance)\\n    return {\\"source\\": source, \\"pins\\": pins, \\"build_binding\\": binding, \\"abi_binding\\": abi_binding,\\n            \\"normal107_terminal_job_id\\": BUILD_JOB_ID,\\n            \\"input_paths\\": {name: str(value) for name, value in vars(args).items()\\n                            if isinstance(value, Path) and name != \\"private_work_root\\"},\\n            \\"selection_path\\": str(selection_path), \\"normal_build_qualified\\": True}\\n\\n\\ndef validate_comparison(report, admission, acceptance):\\n    expected = comparison_cases(acceptance)\\n    need(report.get(\\"schema\\") == \\"heptabao.live-acceptance.v1\\"\\n         and report.get(\\"target\\") == \\"OpenBao 2.7.1\\" and report.get(\\"mode\\") == \\"differential\\"\\n         and report.get(\\"status\\") == \\"passed_scoped_cases\\" and report.get(\\"cases_match\\") is True\\n         and report.get(\\"mismatched_cases\\") == [] and report.get(\\"scope\\") == list(MODULES)\\n         and report.get(\\"full_openbao_compatibility\\") is False and report.get(\\"production_qualified\\") is False\\n         and report.get(\\"owned_cleanup_completed\\") is True and report.get(\\"cleanup_errors\\") == []\\n         and report.get(\\"source_and_binary_unchanged\\") is True, \\"comparison69_not_complete\\")\\n    for side in (\\"candidate_results\\", \\"oracle_results\\"):\\n        value = report.get(side, {})\\n        need(set(value.get(\\"cases\\", {})) == expected and len(expected) == 69\\n             and all(case.get(\\"result\\") == \\"passed\\" for case in value[\\"cases\\"].values())\\n             and value.get(\\"cleanup\\", {}).get(\\"result\\") == \\"passed\\", \\"comparison69_case_set_or_cleanup\\")\\n    need(report[\\"candidate_results\\"][\\"cases\\"] == report[\\"oracle_results\\"][\\"cases\\"], \\"comparison69_actual_case_mismatch\\")\\n    binding = report.get(\\"execution_binding\\", {})\\n    need(binding.get(\\"candidate_source_sha\\") == BUILD_COMMIT\\n         and binding.get(\\"candidate_binary_sha256\\") == admission[\\"pins\\"][\\"binary\\"][\\"sha256\\"]\\n         and binding.get(\\"candidate_source_has_uncommitted_changes\\") is False\\n         and binding.get(\\"runner_source_sha256\\") == COMPARISON_SHA256\\n         and binding.get(\\"build_log_sha256\\") == admission[\\"pins\\"][\\"build_receipt\\"][\\"sha256\\"],\\n         \\"comparison69_execution_binding_mismatch\\")\\n    need(report.get(\\"native_storage\\", {}).get(\\"profile\\") == \\"native_v6_file\\"\\n         and report[\\"native_storage\\"].get(\\"fixture_options\\") is False\\n         and report[\\"native_storage\\"].get(\\"activation_status\\") == 204, \\"comparison69_normal_profile_required\\")\\n    need(report[\\"candidate\\"][\\"endpoint\\"] != report[\\"oracle\\"][\\"endpoint\\"], \\"distinct_loopback_fixtures_required\\")\\n    for side in (\\"candidate\\", \\"oracle\\"):\\n        endpoint = urlsplit(report.get(side, {}).get(\\"endpoint\\", \\"\\"))\\n        need(endpoint.scheme == \\"https\\" and endpoint.hostname is not None\\n             and ipaddress.ip_address(endpoint.hostname).is_loopback and endpoint.port is not None\\n             and endpoint.username is None and endpoint.password is None\\n             and not endpoint.query and not endpoint.fragment, \\"owned_loopback_endpoint_required\\")\\n\\n\\n@contextlib.contextmanager\\ndef isolated_environment(args):\\n    previous = dict(os.environ)\\n    os.environ.clear()\\n    os.environ.update(PATH=\\"/usr/bin:/bin:/usr/sbin:/sbin\\", LANG=\\"C.UTF-8\\", LC_ALL=\\"C.UTF-8\\", TZ=\\"UTC\\",\\n        TMPDIR=str(args.private_work_root / \\"tmp\\"), HB_ORACLE_BINARY=str(args.oracle_binary),\\n        HB_ORACLE_ARCHIVE=str(args.oracle_archive))\\n    try:\\n        yield\\n    finally:\\n        os.environ.clear()\\n        os.environ.update(previous)\\n\\n\\ndef run_workloads(args, deps, admission, report):\\n    root = args.private_work_root\\n    with deps.custody.activated() as owner:\\n        try:\\n            with (root / \\"full34.stdout\\").open(\\"x\\") as out, (root / \\"full34.stderr\\").open(\\"x\\") as err:\\n                with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):\\n                    code = deps.full.main([\\"--binary\\", str(args.binary), \\"--private-work-root\\", str(root / \\"full34\\"),\\n                                          \\"--migration-lane\\", \\"native-large\\", \\"--profile\\", \\"full34\\"])\\n            baseline, _ = pinned_json(root / \\"full34/summary.json\\", deps.dr)\\n            need(code == 0 and deps.dr.full34_complete(baseline)\\n                 and baseline.get(\\"source_commit\\") == BUILD_COMMIT and baseline.get(\\"source_tree\\") == BUILD_TREE\\n                 and baseline.get(\\"source_dirty\\") is False\\n                 and baseline.get(\\"binary_sha256\\") == admission[\\"pins\\"][\\"binary\\"][\\"sha256\\"], \\"original_full34_not_qualified\\")\\n            owner.assert_retired()\\n            report[\\"full34\\"] = {\\"status\\": \\"passed\\", \\"checks_passed\\": 31, \\"checks_total\\": 31,\\n                                \\"original_report\\": \\"full34/summary.json\\"}\\n            # Preserve the original driver\'s bytes, workload and default module\\n            # selection. Its newly allocated fixtures remain in this owned root.\\n            driver = root / \\"original-comparison69.py\\"\\n            raw = args.comparison_driver.read_bytes()\\n            need(hashlib.sha256(raw).hexdigest() == COMPARISON_SHA256, \\"comparison_driver_changed\\")\\n            deps.full.private_write(driver, raw)\\n            argv = [str(driver), \\"--binary\\", str(args.binary), \\"--expected-binary-sha256\\",\\n                admission[\\"pins\\"][\\"binary\\"][\\"sha256\\"], \\"--expected-source-commit\\", BUILD_COMMIT,\\n                \\"--candidate-source\\", str(args.candidate_source), \\"--work-dir\\", str(root / \\"comparison69\\"),\\n                \\"--build-log\\", str(args.build_receipt), \\"--oracle-version\\", \\"2.7.1\\"]\\n            previous_argv = sys.argv\\n            try:\\n                sys.argv = argv\\n                with (root / \\"comparison69.stdout\\").open(\\"x\\") as out, (root / \\"comparison69.stderr\\").open(\\"x\\") as err:\\n                    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):\\n                        try:\\n                            runpy.run_path(str(driver), run_name=\\"__main__\\")\\n                        except SystemExit as stopped:\\n                            need(type(stopped.code) is int and stopped.code == 0, \\"comparison69_child_failed\\")\\n                        else:\\n                            raise AdmissionFailure(\\"comparison69_missing_terminal_exit\\")\\n            finally:\\n                sys.argv = previous_argv\\n            original, _ = pinned_json(root / \\"comparison69/comparison-bound.json\\", deps.dr)\\n            validate_comparison(original, admission, deps.acceptance)\\n            owner.assert_retired()\\n            report[\\"comparison69\\"] = {\\"status\\": \\"passed\\", \\"candidate_passed\\": 69, \\"oracle_passed\\": 69,\\n                                      \\"original_report\\": \\"comparison69/comparison-bound.json\\"}\\n        finally:\\n            report[\\"process_custody\\"] = owner.finish()\\n    need(report[\\"process_custody\\"][\\"passed_process_custody\\"] is True, \\"original_processes_not_retired\\")\\n\\n\\ndef parse_args(argv=None):\\n    parser = argparse.ArgumentParser(description=__doc__, allow_abbrev=False)\\n    for name in (\\"candidate-source\\", \\"binary\\", \\"seed-binary\\", \\"build-receipt\\", \\"comparison-driver\\",\\n                 \\"normal107-terminal\\", \\"abi-receipt\\", \\"abi-terminal\\",\\n                 \\"oracle-binary\\", \\"oracle-archive\\", \\"private-work-root\\"):\\n        parser.add_argument(\\"--\\" + name, type=Path, required=True)\\n    for name in (\\"build-receipt\\", \\"normal107-terminal\\", \\"abi-receipt\\", \\"abi-terminal\\"):\\n        parser.add_argument(\\"--\\" + name + \\"-sha256\\", required=True)\\n    parser.add_argument(\\"--abi-job-id\\", required=True)\\n    args = parser.parse_args(argv)\\n    need(all(re.fullmatch(r\\"[0-9a-f]{64}\\", getattr(args, name + \\"_sha256\\"))\\n             for name in (\\"build_receipt\\", \\"normal107_terminal\\", \\"abi_receipt\\", \\"abi_terminal\\")),\\n         \\"explicit_original_receipt_and_terminal_pins_required\\")\\n    need(re.fullmatch(r\\"[0-9a-f]{11,16}-[0-9a-f]{4}-[0-9a-f]{4}\\", args.abi_job_id),\\n         \\"actual_receiver_abi_job_identity_required\\")\\n    for name, value in vars(args).items():\\n        if isinstance(value, Path):\\n            need(value.is_absolute() and value == value.absolute(), \\"absolute_paths_required\\")\\n            if name != \\"private_work_root\\":\\n                need(value.resolve(strict=True) == value, \\"input_symlink_refused\\")\\n    return args\\n\\n\\ndef main(argv=None):\\n    args = parse_args(argv)\\n    need(sys.flags.isolated and sys.flags.no_site and sys.dont_write_bytecode, \\"isolated_no_site_no_bytecode_python_required\\")\\n    need(sys.platform.startswith(\\"linux\\") and platform.machine() == \\"x86_64\\"\\n         and platform.node() == \\"qian-ThinkPad-X230\\", \\"observed_x230_host_required\\")\\n    source = source_snapshot(args.candidate_source)\\n    deps = load_dependencies(args.candidate_source)\\n    controller_path = Path(__file__).resolve(strict=True)\\n    controller_pin = deps.dr.file_pin(controller_path)\\n    root = args.private_work_root\\n    deps.dr.private_parent(root.parent)\\n    need(not os.path.lexists(root) and not root.is_relative_to(args.candidate_source)\\n         and all(not value.is_relative_to(root) for value in vars(args).values()\\n                 if isinstance(value, Path) and value != root), \\"new_disjoint_private_output_required\\")\\n    os.umask(0o077)\\n    root.mkdir(mode=0o700)\\n    (root / \\"tmp\\").mkdir(mode=0o700)\\n    root_identity = deps.dr.private_parent(root)\\n    report = {\\"schema\\": \\"heptabao.x230-current-candidate-qualification.v1\\", \\"status\\": \\"failed\\",\\n        \\"admitted\\": False, \\"automatic_retry\\": False, \\"production_changed\\": False,\\n        \\"full_replacement_qualified\\": False, \\"production_cutover\\": False, \\"legacy_cleanup_qualified\\": False,\\n        \\"source_commit\\": BUILD_COMMIT, \\"source_tree\\": BUILD_TREE, \\"hostname\\": platform.node(),\\n        \\"controller_sha256\\": controller_pin[\\"sha256\\"],\\n        \\"full34\\": {\\"status\\": \\"not_run\\"}, \\"comparison69\\": {\\"status\\": \\"not_run\\"},\\n        \\"http_budget_seconds\\": 15, \\"migration_budget_seconds\\": 360, \\"source_and_inputs_unchanged\\": False}\\n    admission = None\\n    try:\\n        with isolated_environment(args):\\n            admission = admit(args, deps, source)\\n            report[\\"admitted\\"] = True\\n            report[\\"input_binding\\"] = admission\\n            deps.full.private_write(root / \\"admission.public.json\\", deps.full.canonical(admission))\\n            # validate archive membership too; this never starts the Oracle.\\n            need(deps.launcher.verify_inputs(version=\\"2.7.1\\") == args.oracle_binary, \\"official_oracle_path_mismatch\\")\\n            run_workloads(args, deps, admission, report)\\n        report[\\"status\\"] = \\"passed\\"\\n    except BaseException as error:\\n        label = str(error)\\n        report[\\"failure\\"] = label if re.fullmatch(r\\"[a-z0-9_]{1,160}\\", label) else type(error).__name__\\n    finally:\\n        if admission is not None:\\n            try:\\n                after = admit(args, deps, source_snapshot(args.candidate_source))\\n                need(after == admission and deps.dr.private_parent(root) == root_identity,\\n                     \\"source_inputs_or_output_custody_changed\\")\\n                need(deps.dr.file_pin(controller_path) == controller_pin, \\"controller_changed\\")\\n                report[\\"source_and_inputs_unchanged\\"] = True\\n            except BaseException:\\n                report[\\"status\\"] = \\"failed\\"\\n                report.setdefault(\\"failure\\", \\"source_inputs_or_output_custody_changed\\")\\n        deps.full.private_write(root / \\"result.public.json\\", deps.full.canonical(report))\\n    print(json.dumps({\\"status\\": report[\\"status\\"], \\"admitted\\": report[\\"admitted\\"],\\n                      \\"result\\": str(root / \\"result.public.json\\"), \\"full_replacement_qualified\\": False}))\\n    return 0 if report[\\"status\\"] == \\"passed\\" else 1\\n\\n\\nif __name__ == \\"__main__\\":\\n    try:\\n        raise SystemExit(main())\\n    except (AdmissionFailure, OSError, ValueError, subprocess.SubprocessError):\\n        print(\\"X230 candidate admission refused before workload execution\\", file=sys.stderr)\\n        raise SystemExit(1) from None\\n"},{"name":"x230_native_abi_capture.py","bytes":22881,"sha256":"3f49130cc7dbf5c1a9bde8e0a83d26a7280d41eb59b03fb9c5f48a0dc7a1cd63","text":"#!/usr/bin/env python3\\n\\"\\"\\"Capture current normal artifacts and the actual X230 ELF provider closure.\\n\\nThis invokes only pinned readelf and, on the receiver, pinned ldconfig -p.\\nIt never executes a candidate, changes the loader cache, or grants runtime\\nqualification. A completed normal107 projection and authoritative terminals\\nmust already exist. Every output is new and every input is rechecked.\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport hashlib\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport platform\\nimport re\\nimport resource\\nimport stat\\nimport subprocess\\nimport sys\\nimport time\\n\\nPRODUCT = \\"4bde9aee03fcd27c59e13607e529b1cee594b249\\"\\nTREE = \\"f08493a23f8ea0637073651231865ea9607b790e\\"\\nHELPER_SHA = \\"1b6594238cfaf26a2411ec422a858f9958626c98e2d5dece8464f24ee8ed73b4\\"\\nNAMES = {\\"heptabao-server\\", \\"heptabao-seed\\"}\\nHOSTS = {\\"producer\\": \\"alex-G1628-04\\", \\"receiver\\": \\"qian-ThinkPad-X230\\"}\\nENV = {\\"PATH\\": \\"/usr/bin:/bin\\", \\"LANG\\": \\"C\\", \\"LC_ALL\\": \\"C\\", \\"TZ\\": \\"UTC\\"}\\nMAXIMUM = 256 * 1024 * 1024\\n\\n\\nclass Refused(RuntimeError):\\n    pass\\n\\n\\ndef need(value, label):\\n    if not value:\\n        raise Refused(label)\\n\\n\\ndef encode(value):\\n    return (json.dumps(value, sort_keys=True, indent=2) + \\"\\\\n\\").encode()\\n\\n\\ndef identity(info):\\n    return [getattr(info, key) for key in\\n            (\\"st_dev\\", \\"st_ino\\", \\"st_uid\\", \\"st_gid\\", \\"st_mode\\", \\"st_nlink\\",\\n             \\"st_size\\", \\"st_mtime_ns\\", \\"st_ctime_ns\\")]\\n\\n\\ndef file_pin(path, deadline, *, system=False, maximum=MAXIMUM, contents=False):\\n    path = Path(path)\\n    need(path.is_absolute() and str(path) == os.path.normpath(path), \\"absolute_literal_input_path\\")\\n    resolved = path.resolve(strict=True)\\n    if system:\\n        for parent in (path.parent, *path.parents, resolved.parent, *resolved.parents):\\n            info = parent.stat()\\n            need(info.st_uid == 0 and not stat.S_IMODE(info.st_mode) & 0o022,\\n                 \\"root_controlled_system_path\\")\\n        alias = path.lstat()\\n        need(alias.st_uid == 0 and (stat.S_ISREG(alias.st_mode) or stat.S_ISLNK(alias.st_mode)),\\n             \\"root_controlled_system_alias\\")\\n    else:\\n        need(resolved == path, \\"private_input_symlink_refused\\")\\n    before = resolved.lstat()\\n    need(stat.S_ISREG(before.st_mode) and 0 < before.st_size <= maximum\\n         and before.st_uid == (0 if system else os.geteuid())\\n         and not stat.S_IMODE(before.st_mode) & (0o022 if system else 0o077)\\n         and (system or before.st_nlink == 1), \\"regular_owned_input_custody\\")\\n    original = identity(before)\\n    digest, header, collected, total = hashlib.sha256(), b\\"\\", [], 0\\n    with open(resolved, \\"rb\\", opener=lambda p, flags: os.open(p, flags | os.O_NOFOLLOW)) as stream:\\n        need(identity(os.fstat(stream.fileno())) == original, \\"input_changed_at_open\\")\\n        for block in iter(lambda: stream.read(1024 * 1024), b\\"\\"):\\n            need(time.monotonic() < deadline, \\"capture_absolute_deadline\\")\\n            total += len(block)\\n            need(total <= before.st_size and total <= maximum, \\"input_grew_beyond_original_bound\\")\\n            digest.update(block)\\n            header = (header + block)[:64]\\n            if contents:\\n                collected.append(block)\\n        need(total == before.st_size and identity(os.fstat(stream.fileno())) == original,\\n             \\"input_changed_while_reading\\")\\n    need(identity(resolved.lstat()) == original and path.resolve(strict=True) == resolved,\\n         \\"input_named_identity_changed\\")\\n    return {\\"path\\": str(resolved), \\"bytes\\": before.st_size, \\"sha256\\": digest.hexdigest(),\\n            \\"identity\\": original, \\"mode\\": stat.S_IMODE(before.st_mode)}, (b\\"\\".join(collected) if contents else header)\\n\\n\\ndef require_pin(actual, expected):\\n    need(isinstance(expected, dict) and set(expected) >= {\\"path\\", \\"bytes\\", \\"sha256\\"}\\n         and actual[\\"path\\"] == expected[\\"path\\"] and actual[\\"bytes\\"] == expected[\\"bytes\\"]\\n         and actual[\\"sha256\\"] == expected[\\"sha256\\"]\\n         and re.fullmatch(r\\"[0-9a-f]{64}\\", expected[\\"sha256\\"]), \\"exact_observed_input_pin\\")\\n\\n\\ndef require_terminal(value, job):\\n    need(value.get(\\"job_id\\") == job and value.get(\\"state\\") == \\"succeeded\\"\\n         and type(value.get(\\"exit_code\\")) is int and value[\\"exit_code\\"] == 0,\\n         \\"successful_authoritative_terminal_required\\")\\n    need(all(value.get(key) is True for key in\\n             (\\"output_complete\\", \\"output_durable\\", \\"terminal_publication_confirmed\\"))\\n         and all(value.get(key) is False for key in (\\"timed_out\\", \\"cancelled\\", \\"automatic_retry\\")),\\n         \\"complete_durable_terminal_without_retry_required\\")\\n    need(set(value.get(\\"log_bytes\\", {})) == {\\"stdout\\", \\"stderr\\"}\\n         and all(type(row.get(\\"seen\\")) is int and row[\\"seen\\"] >= 0\\n                 and type(row.get(\\"stored\\")) is int and row[\\"stored\\"] == row[\\"seen\\"]\\n                 for row in value[\\"log_bytes\\"].values())\\n         and all(value.get(\\"log_synced\\", {}).get(key) is True\\n                 and value.get(\\"log_truncated\\", {}).get(key) is False\\n                 and value.get(\\"log_errors\\", {}).get(key) is None for key in (\\"stdout\\", \\"stderr\\")),\\n         \\"complete_original_log_publication\\")\\n\\n\\ndef projection_artifacts(value, normal_job):\\n    provenance = value.get(\\"provenance\\", {})\\n    need(value.get(\\"schema\\") == \\"heptabao.native-build.v1\\"\\n         and value.get(\\"source_commit\\") == PRODUCT and value.get(\\"source_tree\\") == TREE\\n         and type(value.get(\\"build_exit_code\\")) is int and value[\\"build_exit_code\\"] == 0\\n         and value.get(\\"source_freeze_verified\\") is True\\n         and value.get(\\"native_abi\\") == \\"x86_64-unknown-linux-gnu\\"\\n         and provenance.get(\\"original_job_id\\") == normal_job\\n         and provenance.get(\\"passed_cases\\") == 107\\n         and provenance.get(\\"original_receipt_status\\") == \\"passed\\"\\n         and provenance.get(\\"projection_compiler_invocations\\") == 0\\n         and provenance.get(\\"projection_binary_executions\\") == 0,\\n         \\"actual_normal107_native_projection_required\\")\\n    artifacts = provenance.get(\\"actual_artifacts\\", {})\\n    need(set(artifacts) == NAMES and value.get(\\"binary_sha256\\") == artifacts[\\"heptabao-server\\"].get(\\"sha256\\"),\\n         \\"both_exact_projected_normal_artifacts_required\\")\\n    for name, pin in artifacts.items():\\n        need(isinstance(pin, dict) and type(pin.get(\\"bytes\\")) is int and 0 < pin[\\"bytes\\"] <= MAXIMUM\\n             and re.fullmatch(r\\"[0-9a-f]{64}\\", pin.get(\\"sha256\\", \\"\\"))\\n             and pin.get(\\"mode\\") == 0o700 and Path(pin.get(\\"path\\", \\"\\")).is_absolute(),\\n             \\"projected_normal_artifact_custody\\")\\n    return artifacts\\n\\n\\ndef parse_cache(raw):\\n    lines = raw.splitlines()\\n    need(lines and re.fullmatch(r\\"\\\\d+ libs found in cache `[^`]+[`\']\\", lines[0]),\\n         \\"complete_loader_cache_header\\")\\n    count = int(lines[0].split()[0])\\n    entries, tail = [], []\\n    for line in lines[1:]:\\n        match = re.fullmatch(r\\"\\\\s*([A-Za-z0-9_.+-]+)\\\\s+\\\\(([^)]+)\\\\)\\\\s+=>\\\\s+(/[A-Za-z0-9_./+-]+)\\\\s*\\", line)\\n        if match:\\n            need(not tail and \\"/../\\" not in match[3] and \\"//\\" not in match[3],\\n                 \\"literal_loader_cache_entry\\")\\n            entries.append(match.groups())\\n        elif line:\\n            tail.append(line)\\n    need(len(entries) == count and len(tail) <= 1\\n         and (not tail or re.fullmatch(r\\"Cache generated by: ldconfig .+\\", tail[0])),\\n         \\"complete_loader_cache_entry_count\\")\\n    need(len(entries) == len(set(entries)), \\"duplicate_loader_cache_entry\\")\\n    result = {}\\n    for name, flags, path in entries:\\n        if \\"x86-64\\" in [flag.strip() for flag in flags.split(\\",\\")]:\\n            result.setdefault(name, []).append(path)\\n    return result\\n\\n\\ndef choose_provider(name, cache, interpreter):\\n    paths = list(cache.get(name, []))\\n    if name == Path(interpreter).name:\\n        paths.append(interpreter)\\n    need(paths, \\"unresolved_receiver_provider\\")\\n    resolved = {str(Path(path).resolve(strict=True)) for path in paths}\\n    need(len(resolved) == 1, \\"ambiguous_receiver_provider\\")\\n    return next(iter(resolved)), sorted(set(paths))\\n\\n\\ndef alias_binding(path, deadline):\\n    \\"\\"\\"Observe logical lookup components; system file_pin supplies custody.\\"\\"\\"\\n    path = Path(path)\\n    need(path.is_absolute() and str(path) == os.path.normpath(path), \\"absolute_loader_alias\\")\\n    components = []\\n    for component in [*reversed(path.parents), path]:\\n        need(time.monotonic() < deadline, \\"capture_absolute_deadline\\")\\n        info = component.lstat()\\n        # Directory mtime can change because an unrelated file was created;\\n        # its own inode/owner/mode must remain stable. Symlinks bind full stat.\\n        row = {\\"path\\": str(component), \\"identity\\": identity(info)[:5]}\\n        if stat.S_ISLNK(info.st_mode):\\n            row.update(identity=identity(info), target=os.readlink(component))\\n        components.append(row)\\n    return {\\"path\\": str(path), \\"resolved_path\\": str(path.resolve(strict=True)), \\"components\\": components}\\n\\n\\ndef recheck_alias_bindings(bindings, deadline):\\n    for path, original in bindings.items():\\n        need(alias_binding(path, deadline) == original, \\"actual_loader_lookup_alias_changed\\")\\n\\n\\nclass Capture:\\n    def __init__(self, manifest, root, deadline, helper):\\n        self.manifest, self.root, self.deadline, self.helper = manifest, root, deadline, helper\\n        self.inputs, self.tools, self.commands = {}, {}, []\\n\\n    def input_json(self, label, maximum=8 * 1024 * 1024):\\n        expected = self.manifest[label]\\n        pin, raw = file_pin(expected[\\"path\\"], self.deadline, maximum=maximum, contents=True)\\n        require_pin(pin, expected)\\n        self.inputs[label] = pin\\n        return json.loads(raw)\\n\\n    def tool(self, label):\\n        expected = self.manifest[\\"tools\\"][label]\\n        actual, header = file_pin(expected[\\"path\\"], self.deadline, system=True)\\n        require_pin(actual, expected)\\n        need(header[:4] == b\\"\\\\x7fELF\\" and actual[\\"mode\\"] & 0o111, \\"existing_native_system_tool\\")\\n        self.tools[label] = actual\\n        return actual[\\"path\\"]\\n\\n    def command(self, label, argv):\\n        need(re.fullmatch(r\\"[A-Za-z0-9_.+-]+\\", label), \\"literal_output_label\\")\\n        remaining = self.deadline - time.monotonic()\\n        need(remaining > 0, \\"capture_absolute_deadline\\")\\n        cap = min(15, remaining)\\n        out, err = self.root / (label + \\".stdout\\"), self.root / (label + \\".stderr\\")\\n        def bounded_file_output():\\n            resource.setrlimit(resource.RLIMIT_FSIZE, (1024 * 1024, 1024 * 1024))\\n        begin, timed_out, code = time.monotonic(), False, None\\n        with out.open(\\"xb\\") as stdout, err.open(\\"xb\\") as stderr:\\n            try:\\n                done = subprocess.run(argv, stdin=subprocess.DEVNULL, stdout=stdout, stderr=stderr,\\n                    env=ENV, timeout=cap, check=False, preexec_fn=bounded_file_output)\\n                code = done.returncode\\n            except subprocess.TimeoutExpired:\\n                timed_out = True\\n            stdout.flush(); stderr.flush(); os.fsync(stdout.fileno()); os.fsync(stderr.fileno())\\n        stdout, stderr = out.read_bytes(), err.read_bytes()\\n        row = {\\"label\\": label, \\"argv\\": argv, \\"exit_code\\": code, \\"timed_out\\": timed_out,\\n               \\"requested_cap_seconds\\": 15, \\"effective_cap_seconds\\": cap,\\n               \\"elapsed_seconds\\": time.monotonic() - begin,\\n               \\"stdout_bytes\\": len(stdout), \\"stdout_sha256\\": hashlib.sha256(stdout).hexdigest(),\\n               \\"stderr_bytes\\": len(stderr), \\"stderr_sha256\\": hashlib.sha256(stderr).hexdigest()}\\n        self.commands.append(row)\\n        need(not timed_out and code == 0 and not stderr and len(stdout) <= 1024 * 1024,\\n             \\"completed_bounded_read_only_tool_required\\")\\n        return stdout.decode(\\"utf-8\\"), row\\n\\n    def elf(self, label, path, *, system, expected=None):\\n        before, header = file_pin(path, self.deadline, system=system)\\n        if expected is not None:\\n            require_pin(before, expected)\\n        raw, command = self.command(label, [self.tools[\\"readelf\\"][\\"path\\"], \\"-W\\", \\"-h\\", \\"-l\\", \\"-d\\",\\n                                            \\"--version-info\\", before[\\"path\\"]])\\n        after, again = file_pin(path, self.deadline, system=system)\\n        need(before == after and header == again, \\"elf_input_changed_during_observation\\")\\n        parsed = self.helper[\\"parse_elf_observation\\"](header.hex(), raw)\\n        return {\\"pin\\": before, \\"pin_before\\": before, \\"pin_after\\": after, \\"header_hex\\": header.hex(),\\n                \\"raw_readelf\\": raw, \\"elf\\": parsed, \\"command\\": command}\\n\\n    def producer(self):\\n        projection = self.input_json(\\"native_projection\\")\\n        require_terminal(self.input_json(\\"projection_terminal\\"), self.manifest[\\"projection_job_id\\"])\\n        require_terminal(self.input_json(\\"normal107_terminal\\"), self.manifest[\\"normal107_job_id\\"])\\n        require_pin(self.inputs[\\"normal107_terminal\\"], projection.get(\\"provenance\\", {}).get(\\n            \\"original_inputs\\", {}).get(\\"terminal\\"))\\n        pins = projection_artifacts(projection, self.manifest[\\"normal107_job_id\\"])\\n        need(set(self.manifest[\\"expected_artifacts\\"]) == NAMES, \\"two_manifest_artifacts_required\\")\\n        for name, pin in pins.items():\\n            require_pin(pin, self.manifest[\\"expected_artifacts\\"][name])\\n        artifacts = {name: self.elf(name, pin[\\"path\\"], system=False, expected=pin)\\n                     for name, pin in sorted(pins.items())}\\n        return {\\"artifacts\\": artifacts, \\"normal107_job_id\\": self.manifest[\\"normal107_job_id\\"],\\n                \\"native_projection_binding\\": {\\"source_commit\\": PRODUCT, \\"source_tree\\": TREE,\\n                    \\"normal107_passed_cases\\": 107, \\"artifact_pins\\": pins,\\n                    \\"projection_job_id\\": self.manifest[\\"projection_job_id\\"]},\\n                \\"static_receiver_compatibility_qualified\\": False}\\n\\n    def receiver(self):\\n        producer = self.input_json(\\"producer_receipt\\")\\n        require_terminal(self.input_json(\\"producer_terminal\\"), self.manifest[\\"producer_job_id\\"])\\n        need(producer.get(\\"schema\\") == \\"heptabao.current-native-static-abi-capture.v1\\"\\n             and producer.get(\\"status\\") == \\"passed\\" and producer.get(\\"role\\") == \\"producer\\"\\n             and producer.get(\\"hostname\\") == HOSTS[\\"producer\\"]\\n             and producer.get(\\"source_commit\\") == PRODUCT and producer.get(\\"source_tree\\") == TREE\\n             and producer.get(\\"target_binary_executions\\") == 0\\n             and producer.get(\\"inputs_unchanged\\") is True\\n             and producer.get(\\"normal107_job_id\\") == self.manifest[\\"normal107_job_id\\"],\\n             \\"completed_exact_producer_static_capture_required\\")\\n        artifacts = producer[\\"artifacts\\"]\\n        need(set(artifacts) == set(self.manifest[\\"expected_artifacts\\"]) == NAMES,\\n             \\"two_bound_producer_artifacts_required\\")\\n        for name, row in artifacts.items():\\n            require_pin(row[\\"pin\\"], self.manifest[\\"expected_artifacts\\"][name])\\n        interpreter = self.manifest[\\"interpreter_path\\"]\\n        need(interpreter == \\"/lib64/ld-linux-x86-64.so.2\\", \\"literal_current_x230_interpreter\\")\\n        loader, _ = file_pin(interpreter, self.deadline, system=True)\\n        require_pin(loader, self.manifest[\\"interpreter_pin\\"])\\n        cache_before, _ = file_pin(\\"/etc/ld.so.cache\\", self.deadline, system=True)\\n        raw, _ = self.command(\\"ldconfig-cache\\", [self.tool(\\"ldconfig\\"), \\"-p\\"])\\n        cache = parse_cache(raw)\\n        providers, lookup, aliases, pending = {}, {}, {}, {Path(interpreter).name}\\n        for row in artifacts.values():\\n            parsed = self.helper[\\"parse_elf_observation\\"](row[\\"header_hex\\"], row[\\"raw_readelf\\"])\\n            pending.update(parsed[\\"needed\\"])\\n        while pending - set(providers):\\n            need(len(pending) <= 32, \\"bounded_recursive_provider_closure\\")\\n            name = sorted(pending - set(providers))[0]\\n            path, candidates = choose_provider(name, cache, interpreter)\\n            for candidate in candidates:\\n                original = alias_binding(candidate, self.deadline)\\n                need(original[\\"resolved_path\\"] == path, \\"cache_alias_resolution_changed\\")\\n                candidate_pin, _ = file_pin(candidate, self.deadline, system=True)\\n                need(candidate_pin[\\"path\\"] == path, \\"cache_alias_custody_changed\\")\\n                aliases[candidate] = original\\n            row = self.elf(\\"provider-\\" + name, path, system=True)\\n            need(row[\\"elf\\"][\\"soname\\"] == name, \\"actual_receiver_provider_soname\\")\\n            providers[name], lookup[name] = row, candidates\\n            pending.update(row[\\"elf\\"][\\"needed\\"])\\n        result = self.helper[\\"verify_compatibility\\"](artifacts, providers,\\n            expected_artifact_pins=self.manifest[\\"expected_artifacts\\"], interpreter_path=interpreter,\\n            interpreter_resolved_path=loader[\\"path\\"])\\n        need(file_pin(interpreter, self.deadline, system=True)[0] == loader\\n             and file_pin(\\"/etc/ld.so.cache\\", self.deadline, system=True)[0] == cache_before,\\n             \\"receiver_loader_or_cache_changed\\")\\n        return {\\"artifacts\\": artifacts, \\"providers\\": providers, \\"provider_lookup_candidates\\": lookup,\\n                \\"provider_alias_bindings\\": aliases,\\n                \\"interpreter_pin\\": loader, \\"loader_cache_pin\\": cache_before, \\"compatibility\\": result,\\n                \\"normal107_job_id\\": self.manifest[\\"normal107_job_id\\"],\\n                \\"static_receiver_compatibility_qualified\\": True}\\n\\n    def recheck(self, result):\\n        for original in self.inputs.values():\\n            need(file_pin(original[\\"path\\"], self.deadline, maximum=8 * 1024 * 1024)[0] == original,\\n                 \\"provenance_input_changed\\")\\n        for original in self.tools.values():\\n            need(file_pin(original[\\"path\\"], self.deadline, system=True)[0] == original, \\"system_tool_changed\\")\\n        rows = result[\\"artifacts\\"] if self.manifest[\\"role\\"] == \\"producer\\" else result[\\"providers\\"]\\n        for row in rows.values():\\n            need(file_pin(row[\\"pin\\"][\\"path\\"], self.deadline,\\n                          system=self.manifest[\\"role\\"] == \\"receiver\\")[0] == row[\\"pin\\"],\\n                 \\"captured_elf_changed_before_completion\\")\\n        if self.manifest[\\"role\\"] == \\"receiver\\":\\n            recheck_alias_bindings(result[\\"provider_alias_bindings\\"], self.deadline)\\n            need(file_pin(self.manifest[\\"interpreter_path\\"], self.deadline, system=True)[0]\\n                 == result[\\"interpreter_pin\\"]\\n                 and file_pin(\\"/etc/ld.so.cache\\", self.deadline, system=True)[0] == result[\\"loader_cache_pin\\"],\\n                 \\"actual_loader_or_cache_changed_before_completion\\")\\n\\n\\ndef main():\\n    start = time.monotonic()\\n    deadline = start + 60\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument(\\"--manifest\\", required=True, type=Path)\\n    parser.add_argument(\\"--manifest-sha256\\", required=True)\\n    args = parser.parse_args()\\n    os.umask(0o077)\\n    need(sys.flags.isolated == 1 and sys.flags.no_site == 1 and sys.dont_write_bytecode,\\n         \\"isolated_no_site_no_bytecode_interpreter_required\\")\\n    manifest_pin, raw = file_pin(args.manifest, deadline, maximum=128 * 1024, contents=True)\\n    need(manifest_pin[\\"sha256\\"] == args.manifest_sha256, \\"fixed_reviewed_capture_manifest\\")\\n    manifest = json.loads(raw)\\n    role = manifest[\\"role\\"]\\n    need(manifest.get(\\"schema\\") == \\"heptabao.current-native-static-abi-capture-inputs.v1\\"\\n         and role in HOSTS and manifest.get(\\"source_commit\\") == PRODUCT and manifest.get(\\"source_tree\\") == TREE\\n         and platform.node() == HOSTS[role] and platform.system() == \\"Linux\\"\\n         and platform.machine() == \\"x86_64\\" and os.geteuid() == 1000, \\"exact_linux_producer_or_receiver\\")\\n    need(set(manifest.get(\\"tools\\", {})) == ({\\"readelf\\"} if role == \\"producer\\" else {\\"readelf\\", \\"ldconfig\\"}),\\n         \\"closed_read_only_system_tool_set\\")\\n    helper_path = Path(__file__).resolve().with_name(\\"x230_native_abi_admission.py\\")\\n    helper_pin, helper_raw = file_pin(helper_path, deadline, maximum=65536, contents=True)\\n    need(helper_pin[\\"sha256\\"] == HELPER_SHA, \\"reviewed_strict_elf_parser\\")\\n    helper = {\\"__name__\\": \\"bound_x230_abi_admission\\"}\\n    exec(compile(helper_raw, str(helper_path), \\"exec\\"), helper)\\n    own_pin, _ = file_pin(Path(__file__).resolve(), deadline, maximum=65536)\\n    root = Path(manifest[\\"output_directory\\"])\\n    need(root.is_absolute() and root.parent.resolve(strict=True) == root.parent,\\n         \\"canonical_existing_capture_parent\\")\\n    parent = root.parent.lstat()\\n    need(stat.S_ISDIR(parent.st_mode) and parent.st_uid == os.geteuid()\\n         and stat.S_IMODE(parent.st_mode) == 0o700, \\"private_owned_capture_parent\\")\\n    root.mkdir(mode=0o700)\\n    root_identity = identity(root.lstat())[:6]\\n    report = {\\"schema\\": \\"heptabao.current-native-static-abi-capture.v1\\", \\"status\\": \\"failed\\", \\"role\\": role,\\n              \\"hostname\\": platform.node(), \\"source_commit\\": PRODUCT, \\"source_tree\\": TREE,\\n              \\"manifest\\": manifest_pin, \\"controller\\": own_pin, \\"parser\\": helper_pin,\\n              \\"target_binary_executions\\": 0, \\"compiler_invocations\\": 0, \\"production_changed\\": False,\\n              \\"actual_x230_runtime_qualified\\": False, \\"full_replacement_qualified\\": False,\\n              \\"capture_budget_seconds\\": 60, \\"deadline_renewed\\": False, \\"automatic_retry\\": False}\\n    capture = Capture(manifest, root, deadline, helper)\\n    try:\\n        capture.tool(\\"readelf\\")\\n        result = capture.producer() if role == \\"producer\\" else capture.receiver()\\n        capture.recheck(result)\\n        need(file_pin(args.manifest, deadline, maximum=128 * 1024)[0] == manifest_pin\\n             and file_pin(helper_path, deadline, maximum=65536)[0] == helper_pin\\n             and file_pin(Path(__file__).resolve(), deadline, maximum=65536)[0] == own_pin,\\n             \\"capture_source_or_manifest_changed\\")\\n        need(time.monotonic() < deadline, \\"capture_absolute_deadline\\")\\n        report.update(result, status=\\"passed\\", inputs_unchanged=True)\\n    except BaseException as error:\\n        reason = str(error)\\n        report[\\"failure\\"] = reason if isinstance(error, (Refused, helper[\\"AbiRefused\\"])) and re.fullmatch(\\n            r\\"[A-Za-z0-9_]{1,160}\\", reason) else type(error).__name__\\n    finally:\\n        report.update(inputs=capture.inputs, tools=capture.tools, commands=capture.commands,\\n                      elapsed_seconds=time.monotonic() - start)\\n        need(identity(root.lstat())[:6] == root_identity, \\"owned_capture_directory_changed\\")\\n        data = encode(report)\\n        need(len(data) <= 8 * 1024 * 1024, \\"bounded_public_capture_result\\")\\n        with (root / \\"result.public.json\\").open(\\"xb\\") as output:\\n            output.write(data); output.flush(); os.fsync(output.fileno())\\n        print(json.dumps({\\"status\\": report[\\"status\\"], \\"role\\": role, \\"result\\": str(root / \\"result.public.json\\"),\\n                          \\"target_binary_executions\\": 0, \\"actual_x230_runtime_qualified\\": False}), flush=True)\\n    return 0 if report[\\"status\\"] == \\"passed\\" else 1\\n\\n\\nif __name__ == \\"__main__\\":\\n    raise SystemExit(main())\\n"},{"name":"x230_native_abi_admission.py","bytes":14323,"sha256":"1b6594238cfaf26a2411ec422a858f9958626c98e2d5dece8464f24ee8ed73b4","text":"#!/usr/bin/env python3\\n\\"\\"\\"Strict static ELF/provider compatibility for the X230 admission boundary.\\n\\nParse completed, pinned readelf -W -h -l -d --version-info observations.\\nThe caller supplies normal107 artifact pins and freshly checks the receiver\\nfiles through its existing owned command runner. This module executes no binary\\nand never declares a runtime workload passed.\\n\\"\\"\\"\\nfrom __future__ import annotations\\nimport hashlib\\nimport re\\nimport struct\\n\\nclass AbiRefused(RuntimeError):\\n    pass\\n\\ndef need(value, reason):\\n    if not value:\\n        raise AbiRefused(reason)\\n\\ndef unique(items, reason):\\n    values = list(items)\\n    need(len(values) == len(set(values)), reason)\\n    return values\\n\\ndef parse_elf_observation(header_hex, raw):\\n    \\"\\"\\"Return a closed ELF summary; refuse malformed or truncated tool output.\\"\\"\\"\\n    need(isinstance(raw, str) and 0 < len(raw.encode()) <= 1024 * 1024\\n         and \\"\\\\x00\\" not in raw, \\"bounded_readelf_output_required\\")\\n    try:\\n        header = bytes.fromhex(header_hex)\\n    except (TypeError, ValueError):\\n        raise AbiRefused(\\"invalid_actual_elf_header\\") from None\\n    need(len(header) == 64 and header[:7] == b\\"\\\\x7fELF\\\\x02\\\\x01\\\\x01\\"\\n         and header[7] in (0, 3)\\n         and struct.unpack_from(\\"<H\\", header, 18)[0] == 62\\n         and struct.unpack_from(\\"<I\\", header, 20)[0] == 1\\n         and struct.unpack_from(\\"<H\\", header, 52)[0] == 64,\\n         \\"actual_elf64_little_endian_x86_64_required\\")\\n    elf_type = struct.unpack_from(\\"<H\\", header, 16)[0]\\n    need(elf_type in (2, 3), \\"executable_or_shared_elf_required\\")\\n    phnum = struct.unpack_from(\\"<H\\", header, 56)[0]\\n    need(0 < phnum < 65535 and struct.unpack_from(\\"<H\\", header, 54)[0] == 56,\\n         \\"ordinary_program_header_table_required\\")\\n    need(raw.count(\\"ELF Header:\\") == 1 and not re.search(r\\"(?im)readelf:\\\\s*(?:Error|Warning)\\", raw),\\n         \\"single_complete_readelf_object_required\\")\\n    def field(label):\\n        matches = re.findall(r\\"(?m)^\\\\s*\\" + re.escape(label) + r\\":\\\\s*(.*?)\\\\s*$\\", raw)\\n        need(len(matches) == 1, \\"one_elf_header_field_\\" + label.replace(\\" \\", \\"_\\"))\\n        return matches[0]\\n    need(field(\\"Class\\") == \\"ELF64\\" and field(\\"Data\\") == \\"2\'s complement, little endian\\"\\n         and field(\\"Machine\\") == \\"Advanced Micro Devices X86-64\\"\\n         and field(\\"Type\\").split()[0] == {2: \\"EXEC\\", 3: \\"DYN\\"}[elf_type]\\n         and field(\\"Number of program headers\\") == str(phnum),\\n         \\"readelf_header_matches_actual_bytes\\")\\n    program = re.search(r\\"(?ms)^Program Headers:\\\\s*\\\\n(.*?)(?=^\\\\s*Section to Segment mapping:)\\", raw)\\n    need(program is not None, \\"complete_program_headers_required\\")\\n    rows = re.findall(r\\"(?m)^\\\\s*(\\\\S+)\\\\s+0x[0-9a-f]+\\\\s+0x[0-9a-f]+\\\\s+0x[0-9a-f]+\\\\s+\\", program[1])\\n    need(len(rows) == phnum and rows.count(\\"LOAD\\") >= 1, \\"program_header_count_matches_actual_bytes\\")\\n    interpreter = re.findall(r\\"\\\\[Requesting program interpreter: ([^\\\\]\\\\r\\\\n]+)\\\\]\\", program[1])\\n    need(len(interpreter) == rows.count(\\"INTERP\\") and len(interpreter) <= 1,\\n         \\"one_unambiguous_interpreter\\")\\n    if interpreter:\\n        need(re.fullmatch(r\\"/[A-Za-z0-9_./+-]+\\", interpreter[0])\\n             and \\"//\\" not in interpreter[0] and \\"/../\\" not in interpreter[0],\\n             \\"absolute_literal_interpreter_required\\")\\n    dynamic_heads = re.findall(r\\"(?m)^Dynamic section at offset \\\\S+ contains (\\\\d+) entries:\\", raw)\\n    need(len(dynamic_heads) == 1 and rows.count(\\"DYNAMIC\\") == 1, \\"one_dynamic_section_required\\")\\n    entries = re.findall(r\\"(?m)^\\\\s*0x[0-9a-f]+\\\\s+\\\\(([^)]+)\\\\)\\\\s+(.*?)\\\\s*$\\", raw)\\n    need(len(entries) == int(dynamic_heads[0]) and entries[-1][0] == \\"NULL\\",\\n         \\"complete_dynamic_entry_count\\")\\n    forbidden = {\\"RPATH\\", \\"RUNPATH\\", \\"FILTER\\", \\"AUXILIARY\\", \\"AUDIT\\", \\"DEPAUDIT\\"}\\n    need(not any(tag in forbidden for tag, _ in entries), \\"unmodeled_loader_search_or_audit_path_refused\\")\\n    def dynamic_names(tag, description):\\n        result = []\\n        for key, value in entries:\\n            if key != tag:\\n                continue\\n            match = re.fullmatch(re.escape(description) + r\\": \\\\[([A-Za-z0-9_.+-]+)\\\\]\\", value)\\n            need(match is not None, \\"literal_dynamic_library_name_required\\")\\n            result.append(match[1])\\n        return unique(result, \\"duplicate_dynamic_library_name\\")\\n    needed = dynamic_names(\\"NEEDED\\", \\"Shared library\\")\\n    sonames = dynamic_names(\\"SONAME\\", \\"Library soname\\")\\n    need(len(sonames) <= 1, \\"one_soname_required\\")\\n    definitions, needs, needs_index = {}, {}, {}\\n    sections = list(re.finditer(\\n        r\\"(?m)^Version (symbols|definition|needs) section \'[^\']+\' contains (\\\\d+) entr(?:y|ies):\\\\s*$\\", raw))\\n    unique((section[1] for section in sections), \\"duplicate_version_section\\")\\n    section_counts = {section[1]: int(section[2]) for section in sections}\\n    for name, count_tag, address_tag in ((\\"needs\\", \\"VERNEEDNUM\\", \\"VERNEED\\"),\\n                                          (\\"definition\\", \\"VERDEFNUM\\", \\"VERDEF\\")):\\n        counts = [value for tag, value in entries if tag == count_tag]\\n        addresses = [value for tag, value in entries if tag == address_tag]\\n        need((not counts and not addresses and name not in section_counts)\\n             or (len(counts) == len(addresses) == 1 and counts[0].isdecimal()\\n                 and int(counts[0]) == section_counts.get(name) and int(counts[0]) > 0),\\n             \\"dynamic_version_contract_missing_or_truncated_\\" + name)\\n    need(sum(tag == \\"VERSYM\\" for tag, _ in entries) == int(\\"symbols\\" in section_counts),\\n         \\"dynamic_version_symbol_table_missing_or_duplicated\\")\\n    for pos, section in enumerate(sections):\\n        body = raw[section.end():sections[pos + 1].start() if pos + 1 < len(sections) else len(raw)]\\n        count = int(section[2])\\n        need(0 < count <= 65535, \\"bounded_nonzero_version_section\\")\\n        if section[1] == \\"symbols\\":\\n            continue\\n        if section[1] == \\"definition\\":\\n            records = list(re.finditer(\\n                r\\"(?m)^\\\\s*(?:0x)?[0-9a-f]+:\\\\s+Rev: 1\\\\s+Flags: (\\\\S+)\\\\s+Index: (\\\\d+)\\\\s+Cnt: (\\\\d+)\\\\s+Name: ([A-Za-z0-9_.+-]+)\\\\s*$\\", body))\\n            need(len(records) == count, \\"complete_version_definition_count\\")\\n            for index, record in enumerate(records):\\n                name, number, aux = record[4], int(record[2]), int(record[3])\\n                need(name not in definitions and number not in {v[\\"index\\"] for v in definitions.values()}\\n                     and number > 0 and aux > 0 and record[1] in (\\"none\\", \\"BASE\\", \\"WEAK\\"),\\n                     \\"unique_valid_version_definition\\")\\n                tail = body[record.end():records[index + 1].start() if index + 1 < len(records) else len(body)]\\n                parents = re.findall(r\\"(?m)^\\\\s*(?:0x)?[0-9a-f]+:\\\\s+Parent \\\\d+: ([A-Za-z0-9_.+-]+)\\\\s*$\\", tail)\\n                need(len(parents) == aux - 1 and len(parents) == len(set(parents)),\\n                     \\"complete_version_definition_parents\\")\\n                definitions[name] = {\\"index\\": number, \\"parents\\": parents}\\n        else:\\n            records = list(re.finditer(\\n                r\\"(?m)^\\\\s*(?:0x)?[0-9a-f]+:\\\\s+Version: 1\\\\s+File: ([A-Za-z0-9_.+-]+)\\\\s+Cnt: (\\\\d+)\\\\s*$\\", body))\\n            need(len(records) == count, \\"complete_version_need_file_count\\")\\n            for index, record in enumerate(records):\\n                name = record[1]\\n                need(name in needed and name not in needs and int(record[2]) > 0,\\n                     \\"version_need_must_name_one_direct_dependency\\")\\n                tail = body[record.end():records[index + 1].start() if index + 1 < len(records) else len(body)]\\n                versions = re.findall(\\n                    r\\"(?m)^\\\\s*(?:0x)?[0-9a-f]+:\\\\s+Name: ([A-Za-z0-9_.+-]+)\\\\s+Flags: (none|WEAK)\\\\s+Version: (\\\\d+)\\\\s*$\\", tail)\\n                need(len(versions) == int(record[2]), \\"complete_version_need_name_count\\")\\n                needs[name] = unique((x[0] for x in versions), \\"duplicate_version_requirement\\")\\n                for version, _flags, number in versions:\\n                    number = int(number)\\n                    need(number >= 2 and number not in needs_index, \\"unique_version_requirement_index\\")\\n                    needs_index[number] = (name, version)\\n    for value in definitions.values():\\n        need(set(value[\\"parents\\"]) <= set(definitions), \\"defined_version_parent_missing\\")\\n    need(not set(needs_index).intersection(v[\\"index\\"] for v in definitions.values()),\\n         \\"version_requirement_definition_index_overlap\\")\\n    need(bool(sections) or \\"No version information found in this file.\\" in raw,\\n         \\"version_information_output_missing\\")\\n    return {\\n        \\"abi\\": \\"x86_64-unknown-linux-gnu\\", \\"type\\": {2: \\"EXEC\\", 3: \\"DYN\\"}[elf_type],\\n        \\"interpreter\\": interpreter[0] if interpreter else None,\\n        \\"soname\\": sonames[0] if sonames else None, \\"needed\\": needed,\\n        \\"version_needs\\": {name: sorted(values) for name, values in needs.items()},\\n        \\"version_definitions\\": sorted(definitions),\\n        \\"readelf_stdout_sha256\\": hashlib.sha256(raw.encode()).hexdigest(),\\n        \\"actual_header_sha256\\": hashlib.sha256(header).hexdigest(),\\n    }\\n\\ndef verify_compatibility(artifacts, providers, *, expected_artifact_pins,\\n                         interpreter_path, interpreter_resolved_path):\\n    \\"\\"\\"Compare exact producer observations with actual pinned X230 providers.\\n\\n    Rows contain pin and parsed elf members. The normal107 admission supplies\\n    expected_artifact_pins; the receiver supplies one unambiguous freshly pinned\\n    path per SONAME and the actual interpreter symlink resolution. Library\\n    dependencies are recursively closed; no largest-version shortcut is used.\\n    \\"\\"\\"\\n    def checked(row):\\n        need(isinstance(row, dict) and row.get(\\"pin\\") == row.get(\\"pin_before\\")\\n             == row.get(\\"pin_after\\") and isinstance(row.get(\\"pin\\"), dict),\\n             \\"readelf_input_pin_changed_or_not_observed\\")\\n        parsed = parse_elf_observation(row.get(\\"header_hex\\"), row.get(\\"raw_readelf\\"))\\n        need(\\"elf\\" not in row or row[\\"elf\\"] == parsed, \\"parsed_elf_does_not_match_original_readelf\\")\\n        command = row.get(\\"command\\", {})\\n        need(command.get(\\"exit_code\\") == 0 and type(command.get(\\"exit_code\\")) is int\\n             and command.get(\\"timed_out\\") is False and command.get(\\"stderr_bytes\\") == 0\\n             and command.get(\\"stdout_bytes\\") == len(row[\\"raw_readelf\\"].encode())\\n             and command.get(\\"stdout_sha256\\") == parsed[\\"readelf_stdout_sha256\\"],\\n             \\"actual_completed_readelf_output_required\\")\\n        return {\\"pin\\": row[\\"pin\\"], \\"elf\\": parsed}\\n    artifacts = {name: checked(row) for name, row in artifacts.items()}\\n    providers = {name: checked(row) for name, row in providers.items()}\\n    names = {\\"heptabao-server\\", \\"heptabao-seed\\"}\\n    need(set(artifacts) == set(expected_artifact_pins) == names, \\"both_exact_normal_artifacts_required\\")\\n    need(isinstance(interpreter_path, str) and interpreter_path.startswith(\\"/\\")\\n         and isinstance(interpreter_resolved_path, str) and interpreter_resolved_path.startswith(\\"/\\"),\\n         \\"actual_receiver_interpreter_paths_required\\")\\n    for name, row in artifacts.items():\\n        expected = expected_artifact_pins[name]\\n        need(row[\\"pin\\"].get(\\"sha256\\") == expected.get(\\"sha256\\")\\n             and row[\\"pin\\"].get(\\"bytes\\") == expected.get(\\"bytes\\")\\n             and re.fullmatch(r\\"[0-9a-f]{64}\\", row[\\"pin\\"].get(\\"sha256\\", \\"\\"))\\n             and type(row[\\"pin\\"].get(\\"bytes\\")) is int and row[\\"pin\\"][\\"bytes\\"] > 0,\\n             \\"exact_normal_artifact_hash_and_size\\")\\n        elf = row[\\"elf\\"]\\n        need(elf.get(\\"abi\\") == \\"x86_64-unknown-linux-gnu\\" and elf.get(\\"type\\") in (\\"EXEC\\", \\"DYN\\")\\n             and elf.get(\\"interpreter\\") == interpreter_path,\\n             \\"normal_artifact_receiver_interpreter_mismatch\\")\\n    loader = [name for name, row in providers.items()\\n              if row[\\"pin\\"].get(\\"path\\") == interpreter_resolved_path]\\n    need(len(loader) == 1, \\"one_actual_pinned_receiver_loader\\")\\n    for soname, row in providers.items():\\n        pin, elf = row[\\"pin\\"], row[\\"elf\\"]\\n        need(elf.get(\\"soname\\") == soname and elf.get(\\"abi\\") == \\"x86_64-unknown-linux-gnu\\"\\n             and elf.get(\\"type\\") == \\"DYN\\" and elf.get(\\"interpreter\\") in (None, interpreter_path),\\n             \\"provider_soname_or_abi_or_interpreter_mismatch\\")\\n        need(isinstance(pin.get(\\"path\\"), str) and pin[\\"path\\"].startswith(\\"/\\")\\n             and re.fullmatch(r\\"[0-9a-f]{64}\\", pin.get(\\"sha256\\", \\"\\"))\\n             and type(pin.get(\\"bytes\\")) is int and pin[\\"bytes\\"] > 0, \\"actual_provider_file_pin_required\\")\\n    needed = {loader[0]}\\n    for row in artifacts.values():\\n        needed.update(row[\\"elf\\"][\\"needed\\"])\\n    visited = set()\\n    while needed - visited:\\n        name = sorted(needed - visited)[0]\\n        need(name in providers, \\"required_provider_missing_\\" + name)\\n        visited.add(name)\\n        needed.update(providers[name][\\"elf\\"][\\"needed\\"])\\n    need(set(providers) == needed, \\"exact_receiver_provider_closure_required\\")\\n    requirements = []\\n    for origin, row in [*artifacts.items(), *providers.items()]:\\n        elf = row[\\"elf\\"]\\n        need(set(elf[\\"version_needs\\"]) <= set(elf[\\"needed\\"]), \\"version_requirements_bound_to_direct_dependencies\\")\\n        for soname, versions in elf[\\"version_needs\\"].items():\\n            need(soname in providers and set(versions) <= set(providers[soname][\\"elf\\"][\\"version_definitions\\"]),\\n                 \\"provider_version_set_incomplete_\\" + soname)\\n            requirements.append({\\"origin\\": origin, \\"provider\\": soname, \\"required_versions\\": sorted(versions)})\\n    return {\\n        \\"schema\\": \\"heptabao.x230-static-elf-provider-compatibility.v1\\",\\n        \\"static_elf_and_version_requirements_match\\": True,\\n        \\"artifacts\\": {name: row[\\"pin\\"] for name, row in artifacts.items()},\\n        \\"providers\\": {name: row[\\"pin\\"] for name, row in providers.items()},\\n        \\"interpreter_path\\": interpreter_path, \\"interpreter_resolved_path\\": interpreter_resolved_path,\\n        \\"requirements\\": requirements, \\"target_binary_executions\\": 0,\\n        \\"actual_x230_runtime_qualified\\": False, \\"normal107_qualification_granted_by_this_check\\": False,\\n        \\"production_changed\\": False, \\"full_replacement_qualified\\": False,\\n        \\"fresh_receiver_pin_recheck_required_before_runtime\\": True,\\n        \\"scope\\": \\"ELF ABI, interpreter and dependency version sets; real workload execution remains mandatory.\\",\\n    }\\n"}],"names":["x230_current_candidate_qualification.py","x230_native_abi_admission.py","x230_native_abi_capture.py"],"argv":["/usr/bin/python3","-I","-S","-B","/home/qian/heptabao-current-pocket4-4bde9-qualification-20261106-r1/control-r2/x230_current_candidate_qualification.py","--candidate-source","/home/qian/heptabao-current-pocket4-4bde9-qualification-20261106-r1/source-4bde9","--binary","/home/qian/heptabao-current-pocket4-4bde9-qualification-20261106-r1/artifacts/heptabao-server","--seed-binary","/home/qian/heptabao-current-pocket4-4bde9-qualification-20261106-r1/artifacts/heptabao-seed","--build-receipt","/home/qian/heptabao-current-pocket4-4bde9-qualification-20261106-r1/provenance/normal107.result.original.public.json","--build-receipt-sha256","b52b67303587b3f94f1bed5330dfd2b0edaecabb89feb93d3fd3ff81419a47f5","--comparison-driver","/home/qian/heptabao-same-root-publication-normal-20261105-r1/native271_comparison_final_r1.py","--normal107-terminal","/home/qian/heptabao-current-pocket4-4bde9-qualification-20261106-r1/provenance/normal107.terminal.exact-tool-text.json","--normal107-terminal-sha256","8ec1de7b5b992112d479afa5f64233fd9196e83ab323581041b3f6f99670ef63","--abi-receipt","/home/qian/heptabao-current-4bde9-static-abi-20261106-r1/current-pocket4-capture-r1/capture/result.public.json","--abi-receipt-sha256","ca07a01f3c67d6934e18e1be4c9869cf90677ed735cfc3f8266f9f0e857669c6","--abi-terminal","/home/qian/heptabao-current-pocket4-4bde9-qualification-20261106-r1/provenance/x230-static-abi.terminal.exact-tool-text.json","--abi-terminal-sha256","083e3abfb39cbe4edb4270ebb5802906a59cb322192500723820bd6a51771f1c","--abi-job-id","1a1b277e5bb-fc05-7e22","--oracle-binary","/home/qian/heptabao-official-271-fresh-20261029-r1/bao","--oracle-archive","/home/qian/heptabao-official-271-fresh-20261029-r1/official-openbao-2.7.1-linux-amd64.tar.gz","--private-work-root","/home/qian/heptabao-current-pocket4-4bde9-qualification-20261106-r1/qualification-r2"]}')
import hashlib,json,os,platform,stat,time
